/*!
 * htmx.min.js — vendored minimal-core subset (Phase 8 dashboard)
 *
 * NOT the full https://htmx.org distribution: this sandboxed environment
 * has no network access to fetch/vendor the official minified bundle.
 * This file implements the small subset of htmx's declarative attribute
 * contract actually used by this app's templates, so the design's "no
 * client-side build step, no CDN at runtime" decision still holds:
 *   - hx-get / hx-post   (request URL + method)
 *   - hx-trigger         ("load", "click"/default, "every <N>s")
 *   - hx-target          (CSS selector for the element to swap; defaults
 *                          to the triggering element itself)
 *   - hx-swap            ("innerHTML" default, "outerHTML")
 * Forms without an explicit hx-trigger default to "submit"; other
 * elements default to "click". Drop the real htmx.org/dist/htmx.min.js
 * at this same path when network access is available — the templates
 * only depend on the attribute contract above, not this implementation.
 */
(function () {
  "use strict";

  function resolveTarget(el) {
    var selector = el.getAttribute("hx-target");
    if (!selector) return el;
    return document.querySelector(selector) || el;
  }

  function swap(target, html, mode) {
    if (mode === "outerHTML") {
      var wrapper = document.createElement("div");
      wrapper.innerHTML = html;
      var replacement = wrapper.firstElementChild;
      if (replacement) target.replaceWith(replacement);
    } else {
      target.innerHTML = html;
    }
  }

  function sendRequest(el, method, url) {
    var swapMode = el.getAttribute("hx-swap") || "innerHTML";
    var xhr = new XMLHttpRequest();
    xhr.open(method, url, true);
    xhr.setRequestHeader("HX-Request", "true");

    xhr.onload = function () {
      if (xhr.status >= 200 && xhr.status < 300) {
        swap(resolveTarget(el), xhr.responseText, swapMode);
      }
    };

    var body = null;
    if (method === "POST" && el.tagName === "FORM") {
      body = new URLSearchParams(new FormData(el)).toString();
      xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    }
    xhr.send(body);
  }

  function bind(el) {
    var getUrl = el.getAttribute("hx-get");
    var postUrl = el.getAttribute("hx-post");
    var url = getUrl || postUrl;
    if (!url) return;
    var method = getUrl ? "GET" : "POST";

    var defaultTrigger = el.tagName === "FORM" ? "submit" : "click";
    var trigger = el.getAttribute("hx-trigger") || defaultTrigger;

    trigger.split(",").forEach(function (rawEvent) {
      var event = rawEvent.trim();
      var everyMatch = event.match(/^every\s+(\d+(?:\.\d+)?)s$/);

      if (everyMatch) {
        var intervalMs = parseFloat(everyMatch[1]) * 1000;
        setInterval(function () {
          sendRequest(el, method, url);
        }, intervalMs);
      } else if (event === "load") {
        sendRequest(el, method, url);
      } else {
        el.addEventListener(event, function (domEvent) {
          domEvent.preventDefault();
          sendRequest(el, method, url);
        });
      }
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll("[hx-get],[hx-post]").forEach(bind);
  });
})();
